sourcesContent:
import React,{useEffect,useMemo,useState}from 'react';
import './App.css';
import {roadmap,topicInfo,problems,leaders} from './data/content';

const nav=[['Home','/'],['Roadmap','/roadmap'],['Learn','/learn/arrays'],['Practice','/practice'],['DSA Lab','/visualizer'],['Events','/events'],['Leaderboard','/leaderboard']];
const go=(to)=>{window.history.pushState({},'',to);window.dispatchEvent(new PopStateEvent('popstate'))};
function Button({children,onClick,kind=''}){return <button className={'btn '+kind} onClick={onClick}>{children}<span>→</span></button>}
function Progress({value}){return <div className="progress"><i style={{width:value+'%'}}/></div>}
function Navbar({openSearch}){const [path,setPath]=useState(location.pathname),[open,setOpen]=useState(false);useEffect(()=>{const f=()=>setPath(location.pathname);addEventListener('popstate',f);return()=>removeEventListener('popstate',f)},[]);return <header><a className="brand club-logo" href="/" onClick={e=>{e.preventDefault();go('/')}}><b>ACM</b><span>BV</span><em>DSA</em></a><nav className={open?'shown':''}>{nav.map(([n,p])=><a key={p} className={path===p?'active':''} onClick={()=>{go(p);setOpen(false)}}>{n}</a>)}</nav><div className="nav-right"><button className="search-small" onClick={openSearch}>⌕ <span>Search</span><kbd>⌘ K</kbd></button><a onClick={()=>go('/progress')} className={path==='/progress'?'active':''}>Progress</a><Button onClick={()=>go('/register')}>Join ACM BV</Button><button className="avatar">PJ</button></div><button className="hamburger" onClick={()=>setOpen(!open)} aria-label="Menu">{open?'×':'☰'}</button></header>}
function Footer(){return <footer><div><div className="brand"><b>ACM</b><span>BV</span><em>DSA</em></div><p>Learn. Visualize. Solve. Compete.</p><small>An initiative by ACM Student Chapter<br/>Banasthali Vidyapith</small></div><div className="footer-links">{nav.map(([n,p])=><a key={p} onClick={()=>go(p)}>{n}</a>)}<a href="https://acm-bv.acm.org/" target="_blank" rel="noreferrer">ACM BV ↗</a></div><small>© 2026 ACM Student Chapter, Banasthali Vidyapith</small></footer>}
function GraphVisual(){return <div className="graph-visual"><svg viewBox="0 0 420 270"><path d="M210 38L105 112M210 38l105 74M105 112l-58 82m58-82 57 82m48-82 58 82"/><circle cx="210" cy="38" r="25"/><circle cx="105" cy="112" r="25"/><circle cx="315" cy="112" r="25"/><circle cx="47" cy="194" r="25"/><circle cx="162" cy="194" r="25"/><circle cx="373" cy="194" r="25"/></svg><div className="graph-num n1">10</div><div className="graph-num n2">5</div><div className="graph-num n3">15</div><div className="graph-num n4">3</div><div className="graph-num n5">7</div><div className="graph-num n6">20</div><code>binary_search_tree</code></div>}
