function OrbitalTimeline(){const [selected,setSelected]=useState(0);const events=[['AUG','Arrays & Strings','Begin your DSA series with foundations and problem patterns.'],['SEP','Linked Lists','Learn node-based thinking through an interactive lab.'],['OCT','Stack & Queue','Build LIFO/FIFO intuition with real code exercises.'],['NOV','Trees & Graphs','Explore connected structures and their applications.'],['DEC','Dynamic Programming','Close the year with a strategy-driven challenge.']];return <section className="orbital"><div className="orbit-copy"><p className="eyebrow">EVENT TIMELINE · 2026</p><h2>YOUR ACM BV<br/>LEARNING ORBIT</h2><p>{events[selected][2]}</p><Button onClick={()=>go('/learn/'+(['arrays','linked-list','stack','trees','dynamic-programming'][selected]))}>Open resource</Button></div><div className="orbit-stage"><div className="orbit-ring"/ ><div className="orbit-core"><b>ACM</b><span>BV</span></div>{events.map(([month,title],i)=>{let a=(i*72-90)*Math.PI/180;return <button key={month} className={'orbit-node '+(selected===i?'active':'')} style={{'--x':`${50+43*Math.cos(a)}%`,'--y':`${50+43*Math.sin(a)}%`}} onClick={()=>setSelected(i)}><b>{month}</b><span>{title}</span></button>})}</div></section>}
